DROP TABLE IF EXISTS `calificaciones`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `calificaciones` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `cuaderno_auxiliar_id` bigint(20) unsigned NOT NULL,
  `alumno_id` bigint(20) unsigned NOT NULL,
  `nota_conceptual` varchar(255) DEFAULT NULL,
  `nota_numerica` decimal(4,2) DEFAULT NULL,
  `asistencias_total` int(11) NOT NULL DEFAULT 0,
  `inasistencias_total` int(11) NOT NULL DEFAULT 0,
  `sintesis_pedagogica_ia` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `calificaciones_cuaderno_auxiliar_id_alumno_id_unique` (`cuaderno_auxiliar_id`,`alumno_id`),
  KEY `calificaciones_alumno_id_foreign` (`alumno_id`),
  CONSTRAINT `calificaciones_alumno_id_foreign` FOREIGN KEY (`alumno_id`) REFERENCES `alumnos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `calificaciones_cuaderno_auxiliar_id_foreign` FOREIGN KEY (`cuaderno_auxiliar_id`) REFERENCES `cuadernos_auxiliares` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=176 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
