  `docente_id` bigint(20) unsigned NOT NULL,
  `grado_id` bigint(20) unsigned NOT NULL,
  `materia_id` bigint(20) unsigned DEFAULT NULL,
  `ciclo_lectivo_id` bigint(20) unsigned NOT NULL,
  `periodo` enum('1_trimestre','2_trimestre','3_trimestre','informe_final') NOT NULL,
  `estado` enum('borrador','enviado_vicedireccion','visado_observado','aprobado') NOT NULL DEFAULT 'borrador',
  `observaciones_vicedireccion` text DEFAULT NULL,
  `sintesis_general` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cuaderno_grado_periodo_unico_idx` (`grado_id`,`ciclo_lectivo_id`,`periodo`),
  KEY `cuadernos_auxiliares_materia_id_foreign` (`materia_id`),
  KEY `cuadernos_auxiliares_ciclo_lectivo_id_foreign` (`ciclo_lectivo_id`),
